import{_ as a,C as i,o,c as h,j as n,a as e,E as l,a2 as s}from"./chunks/framework.BdaDpuNZ.js";const f=JSON.parse('{"title":"7. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),g={name:"gdd/changelog.md"},d={id:"latest-main",tabindex:"-1"};function m(u,t,c,b,p,y){const r=i("Badge");return o(),h("div",null,[t[3]||(t[3]=n("h1",{id:"_7-changelog",tabindex:"-1"},[e("7. Changelog "),n("a",{class:"header-anchor",href:"#_7-changelog","aria-label":'Permalink to "7. Changelog"'},"​")],-1)),t[4]||(t[4]=n("p",null,[e("Mỗi phiên bản đã phát hành đều chơi được tại URL riêng. "),n("a",{href:"https://tuandds.github.io/shelf-sort-rush/",target:"_blank",rel:"noreferrer"},"Landing page"),e(" liệt kê tất cả.")],-1)),n("h2",d,[t[0]||(t[0]=e("latest (main) ",-1)),l(r,{type:"tip",text:"Live"}),t[1]||(t[1]=e()),t[2]||(t[2]=n("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),t[5]||(t[5]=s('<ul><li>Chưa có thay đổi từ v0.2.0.</li></ul><p><a href="https://tuandds.github.io/shelf-sort-rush/demo/" target="_blank" rel="noreferrer">Chơi bản latest</a></p><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>Bảng màu mới:</strong> 16 màu lấy từ Marble Drop thay cho 10 màu cũ. 10 màn gốc chơi như cũ, chỉ đổi sang màu Marble Drop gần nhất; thêm 6 màu cho màn mới (lime, purple, brown, crimson, darkgreen, lightblue).</li><li><strong>Level Editor</strong> trên web, nút mới ở trang chủ. 4 cột: <ul><li><strong>Colour Bank:</strong> Active Palette + Bank 16 màu.</li><li><strong>Wave Editor:</strong> vẽ tranh pixel theo từng mảng, xem cả đội hình trên board, bật máy bay ẩn / nối đôi / khối lớn / lõi trùm.</li><li><strong>Plane Editor:</strong> xếp tay từng máy bay (màu, số đạn, ẩn, nối đôi, kéo thả giữa 3 khoang), đối chiếu đạn với số khối, nút 🎲 Random.</li><li><strong>Level Bank:</strong> danh sách màn, lưu trong trình duyệt kèm bản sao lưu, xuất/nhập file JSON, copy TypeScript.</li><li>Chơi thử hoặc Auto Play ngay trong trình duyệt; tab Organizer để xem tổng quan.</li></ul></li><li><strong>Màn xếp tay máy bay:</strong> game chơi đúng thứ tự máy bay đã xếp; nếu hết máy bay mà tranh còn khối, game báo <strong>HẾT MÁY BAY!</strong> thay vì kẹt.</li><li><strong>Chơi màn từ editor:</strong> <code>?custom=1</code> chơi danh sách màn của editor, <code>?level=N</code> vào thẳng màn N, <code>?autoplay=1</code> cho bot tự chơi (tắt rung).</li><li><strong>Game Design Document:</strong> thêm bảng màu mới, luật khoang xếp tay và hướng dẫn <a href="/shelf-sort-rush/v0.2.0/docs/guide/level-editor">Level Editor</a>.</li></ul><p><a href="https://tuandds.github.io/shelf-sort-rush/v0.2.0/demo/" target="_blank" rel="noreferrer">Chơi v0.2.0</a> · <a href="https://tuandds.github.io/shelf-sort-rush/v0.2.0/docs/" target="_blank" rel="noreferrer">Tài liệu v0.2.0</a></p><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><ul><li><strong>Pixel Squadron chơi được:</strong> port toàn bộ gameplay từ prototype HTML gốc sang Phaser 4: chạm khoang chứa để cho máy bay cất cánh, máy bay tự bắn khối cùng màu đang lộ ra, 5 chỗ trên trời, thua khi bế tắc 5 giây.</li><li><strong>10 màn</strong> từ <em>Trái tim</em> tới <em>Trùm cuối</em>, với máy bay ẩn, máy bay nối đôi, khối lớn nhiều độ bền và lõi trùm 20 độ bền.</li><li><strong>Giao diện:</strong> HUD với tiến độ màn, chơi lại, chọn màn; popup giới thiệu tính năng mới; tuỳ biến 5 skin máy bay và 5 loại đạn (lưu trong máy).</li><li><strong>Sân chơi cố định 9:16</strong> (450 × 800, hiển thị 1080 × 1920): độ khó như nhau trên mọi màn hình.</li><li><strong>Game Design Document:</strong> viết đầy đủ luật, số liệu, danh sách màn và dữ liệu cân bằng.</li></ul><p><a href="https://tuandds.github.io/shelf-sort-rush/v0.1.0/demo/" target="_blank" rel="noreferrer">Chơi v0.1.0</a> · <a href="https://tuandds.github.io/shelf-sort-rush/v0.1.0/docs/" target="_blank" rel="noreferrer">Tài liệu v0.1.0</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ngày</th><th>Thay đổi</th></tr></thead><tbody><tr><td>2026-10-12</td><td>Tạo GDD</td></tr><tr><td>2026-10-12</td><td>Viết GDD cho Pixel Squadron (port từ prototype HTML)</td></tr><tr><td>2026-10-12</td><td>Phát hành v0.1.0</td></tr><tr><td>2026-10-15</td><td>Phát hành v0.2.0</td></tr></tbody></table>',10))])}const k=a(g,[["render",m]]);export{f as __pageData,k as default};
